    long long x, y, n;
    cin >> x >> y >> n;
    double min_difference = 1e15;
    long long best_numerator = 0, best_denominator = 1;

    for (long long denominator = 1; denominator <= n; ++denominator) {
        long long numerator = (x * denominator) / y;
        auto evaluate = [&](long long candidate) {
            double diff = fabs(x * denominator - candidate * y) / (double)(y * denominator);
