            return 0;
        }
        if ((x * denominator - (numerator + 1) * y) == 0) {
            cout << numerator + 1 << "/" << denominator;
            return 0;
        }

        evaluate(numerator - 1);
        evaluate(numerator);
        evaluate(numerator + 1);
