import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long x = scanner.nextLong();
        long y = scanner.nextLong();
        long n = scanner.nextLong();

        double minDifference = 1e15;
        long bestNumerator = 0;
        long bestDenominator = 1;

        for (long denominator = 1; denominator <= n; ++denominator) {
            long numerator = (x * denominator) / y;

            // Lambda equivalent as a method
            evaluate(numerator - 1, x, y, denominator);
            evaluate(numerator, x, y, denominator);
            evaluate(numerator + 1, x, y, denominator);

            // Check for exact matches
            if (numerator > 0 && (x * denominator - (numerator - 1) * y) == 0) {
                System.out.println((numerator - 1) + "/" + denominator);
                return;
            }
            if ((x * denominator - numerator * y) == 0) {
                System.out.println(numerator + "/" + denominator);
                return;
            }
            if ((x * denominator - (numerator + 1) * y) == 0) {
                System.out.println((numerator + 1) + "/" + denominator);
                return;
            }
        }

        System.out.println(bestNumerator + "/" + bestDenominator);
    }

    private static void evaluate(long candidate, long x, long y, long denominator) {
        double minDifference = 1e15;
        long bestNumerator = 0;
        long bestDenominator = 1;

        double diff = Math.abs(x * denominator - candidate * y) / (double)(y * denominator);
        if (diff < minDifference) {
            minDifference = diff;
            bestNumerator = candidate;
            bestDenominator = denominator;
        }
    }
}

